    setSupportedSourceLanguageCodes(response.sourceLanguages);
    setSupportedTargetLanguageCodes(response.targetLanguages);
  } catch (error) {
    console.error('Error fetching supported language codes:', error);
  }
};

// Call the fetch function when the component is mounted
onMounted(() => {
  fetchSupportedLanguageCodes();
});

return {
  supportedSourceLanguageCodes,
  supportedTargetLanguageCodes,
};

const languageCodes = mw.config.get("wgContentTranslationSupportedLanguages");
if (!languageCodes) {
    throw new Error("wgContentTranslationSupportedLanguages is missing");
}

} elseif ( preg_match( '/^\s*$/D', $token ) && $this->srcOffset !== null ) {
	// White-space doesn't change SOL state
	$this->clearSOL();
	// Update srcOffset
}

// 9.75rem = 156px to match svg width + account for padding
width: calc( 9.75rem + ( @spacing-50 * 2 ) );
min-height: 156px;
